Section WithSegs.
Variable segs : list Segment.

(* [comment removed for export] *)
Definition magree (P : Z -> Prop) (m m' : word -> option byte) : Prop :=
  forall a, 0 <= a < 2^64 -> P a ->
    m' (wa a) = m (wa a) /\ (wview segs m (wa a) <> None -> wview segs m' (wa a) <> None).

Lemma magree_refl : forall P m, magree P m m.
Proof.
ltac2:(KReplay.run1 (kr_t_DrvAgree ()) ["WithSegs"] "h01Hh11Ph22_Hh33_H0h41ah51mp;1p;2p;3p;4g002Fj10Tg002kj14Tg003Ij13Tg00j^j18Tg00>[j2@Tg00?7j16Tg00JJj2<Tg00?Uj2;Tg00@1j2:Tg00k@j12Tg006Lj31Tg00koj35Tg00Fej19Tg00R>j17Tg00:gj2?Tg00llj4>Tg00mGj3=Tg006fR0p-0[g007D#0R1#0#0R2#0#0#0R3#4#3%42#3R2#8R4[g00NOf0R5'@%61%63'<,;5':f3R3f1R1O1P3f2#2R6O1R7=147p,4segsR8?536%92R2514#7R6f4%23558=142#7[1?47P5X06C>W3W2X40A=155eW5W1o"). Qed.
